    "skillId": "skill-docker",
    "type": "technical",
    "questionType": "mcq",
    "prompt": "How does Docker Healthcheck instruction work?",
    "optionsJson": "[{\"id\":\"opt-c1-14-1\",\"text\":\"Periodically executes a command inside the container to verify application responsiveness (HEALTHY/UNHEALTHY)\",\"isCorrect\":true},{\"id\":\"opt-c1-14-2\",\"text\":\"Checks CPU temperature of the host machine\",\"isCorrect\":false},{\"id\":\"opt-c1-14-3\",\"text\":\"Scans source code for linting errors\",\"isCorrect\":false},{\"id\":\"opt-c1-14-4\",\"text\":\"Verifies SSL certificate expiration on the gateway\",\"isCorrect\":false}]",
