    "domain": "Cloud/DevOps",
    "skillId": "skill-docker",
    "type": "technical",
    "questionType": "mcq",
    "prompt": "Why is caching dependencies separately from application code in Dockerfiles recommended?",
    "optionsJson": "[{\"id\":\"opt-c1-17-1\",\"text\":\"Prevents re-running slow dependency installation (e.g. npm install) when only application source code changes\",\"isCorrect\":true},{\"id\":\"opt-c1-17-2\",\"text\":\"Prevents npm from downloading packages over HTTP\",\"isCorrect\":false},{\"id\":\"opt-c1-17-3\",\"text\":\"Deletes development dependencies automatically\",\"isCorrect\":false},{\"id\":\"opt-c1-17-4\",\"text\":\"Encrypts package-lock.json with SHA-512\",\"isCorrect\":false}]",
    "weight": 1,
