    "skillId": "skill-docker",
    "type": "technical",
    "questionType": "mcq",
    "prompt": "What is the difference between Virtual Machines and Docker Containers?",
    "optionsJson": "[{\"id\":\"opt-c1-20-1\",\"text\":\"VMs virtualize hardware and run a full guest OS kernel; containers share the host OS kernel and isolate user space\",\"isCorrect\":true},{\"id\":\"opt-c1-20-2\",\"text\":\"Containers are slower and consume 10x more RAM than VMs\",\"isCorrect\":false},{\"id\":\"opt-c1-20-3\",\"text\":\"VMs cannot run Linux distributions\",\"isCorrect\":false},{\"id\":\"opt-c1-20-4\",\"text\":\"Containers require hypervisors like VMware ESXi to run\",\"isCorrect\":false}]",
