    "type": "technical",
    "questionType": "mcq",
    "prompt": "What is the role of the Kubernetes Kube-Scheduler in the control plane?",
    "optionsJson": "[{\"id\":\"opt-c2-02-1\",\"text\":\"Assigns newly created unscheduled Pods to optimal worker Nodes based on resource requests and constraints\",\"isCorrect\":true},{\"id\":\"opt-c2-02-2\",\"text\":\"Compiles container images on worker nodes\",\"isCorrect\":false},{\"id\":\"opt-c2-02-3\",\"text\":\"Issues SSL certificates for Ingress controllers\",\"isCorrect\":false},{\"id\":\"opt-c2-02-4\",\"text\":\"Backs up etcd database snapshots to S3\",\"isCorrect\":false}]",
