    "type": "technical",
    "questionType": "mcq",
    "prompt": "In Kubernetes, what is the difference between a ClusterIP and a NodePort service?",
    "optionsJson": "[{\"id\":\"opt-c2-03-1\",\"text\":\"ClusterIP is internal to the cluster; NodePort exposes the service on a static port on each Node IP for external access\",\"isCorrect\":true},{\"id\":\"opt-c2-03-2\",\"text\":\"ClusterIP only supports UDP traffic\",\"isCorrect\":false},{\"id\":\"opt-c2-03-3\",\"text\":\"NodePort is 100x faster than ClusterIP\",\"isCorrect\":false},{\"id\":\"opt-c2-03-4\",\"text\":\"ClusterIP requires AWS Load Balancer Controller\",\"isCorrect\":false}]",
