    "prompt": "What is the difference between a Deployment and a StatefulSet in Kubernetes?",
    "optionsJson": "[{\"id\":\"opt-c2-07-1\",\"text\":\"Deployments manage stateless, interchangeable pods; StatefulSets provide stable network identities and persistent storage per pod\",\"isCorrect\":true},{\"id\":\"opt-c2-07-2\",\"text\":\"StatefulSets cannot scale beyond 1 replica\",\"isCorrect\":false},{\"id\":\"opt-c2-07-3\",\"text\":\"Deployments only run on Windows nodes\",\"isCorrect\":false},{\"id\":\"opt-c2-07-4\",\"text\":\"StatefulSets do not support rolling updates\",\"isCorrect\":false}]",
