    "questionType": "mcq",
    "prompt": "What is a Kubernetes DaemonSet used for?",
    "optionsJson": "[{\"id\":\"opt-c2-08-1\",\"text\":\"Ensures that a copy of a specific Pod runs on all (or selected) worker nodes in the cluster (e.g. fluentd logging, monitoring agents)\",\"isCorrect\":true},{\"id\":\"opt-c2-08-2\",\"text\":\"Deletes idle pods after 1 hour\",\"isCorrect\":false},{\"id\":\"opt-c2-08-3\",\"text\":\"Manages database primary-replica replication\",\"isCorrect\":false},{\"id\":\"opt-c2-08-4\",\"text\":\"Encrypts network communication between pods\",\"isCorrect\":false}]",
