    "questionType": "mcq",
    "prompt": "In Kubernetes resource management, what is the difference between `requests` and `limits`?",
    "optionsJson": "[{\"id\":\"opt-c2-09-1\",\"text\":\"`requests` are guaranteed minimum resources used for scheduling; `limits` are hard maximum boundaries enforced by the kernel\",\"isCorrect\":true},{\"id\":\"opt-c2-09-2\",\"text\":\"`requests` are measured in dollars; `limits` in hours\",\"isCorrect\":false},{\"id\":\"opt-c2-09-3\",\"text\":\"`limits` are only used for GPU nodes\",\"isCorrect\":false},{\"id\":\"opt-c2-09-4\",\"text\":\"`requests` cannot exceed 100 millicores\",\"isCorrect\":false}]",
