    "type": "technical",
    "questionType": "mcq",
    "prompt": "What is the Horizontal Pod Autoscaler (HPA) and how does it scale workloads?",
    "optionsJson": "[{\"id\":\"opt-c2-10-1\",\"text\":\"Automatically adjusts the number of Pod replicas in a Deployment based on observed CPU/memory utilization or custom metrics\",\"isCorrect\":true},{\"id\":\"opt-c2-10-2\",\"text\":\"Adds more physical RAM sticks to worker nodes\",\"isCorrect\":false},{\"id\":\"opt-c2-10-3\",\"text\":\"Scales the cluster from 1 node to 10 nodes in AWS\",\"isCorrect\":false},{\"id\":\"opt-c2-10-4\",\"text\":\"Compresses container log files when disk is 90% full\",\"isCorrect\":false}]",
