    "questionType": "mcq",
    "prompt": "What is the purpose of Kubernetes ConfigMaps and Secrets?",
    "optionsJson": "[{\"id\":\"opt-c2-11-1\",\"text\":\"Decouples environment-specific configuration and confidential credentials (keys/tokens) from container image binaries\",\"isCorrect\":true},{\"id\":\"opt-c2-11-2\",\"text\":\"Encrypts Kubernetes source code repositories\",\"isCorrect\":false},{\"id\":\"opt-c2-11-3\",\"text\":\"Compiles Go binaries inside the control plane\",\"isCorrect\":false},{\"id\":\"opt-c2-11-4\",\"text\":\"Manages DNS records on GoDaddy\",\"isCorrect\":false}]",
