    "prompt": "What is the function of the Kubernetes Kubelet component?",
    "optionsJson": "[{\"id\":\"opt-c2-13-1\",\"text\":\"An agent that runs on each worker node to ensure containers described in PodSpecs are running and healthy\",\"isCorrect\":true},{\"id\":\"opt-c2-13-2\",\"text\":\"A command-line tool used by developers on laptops\",\"isCorrect\":false},{\"id\":\"opt-c2-13-3\",\"text\":\"The load balancer distributing requests across master nodes\",\"isCorrect\":false},{\"id\":\"opt-c2-13-4\",\"text\":\"A certificate authority issuing SSH keys\",\"isCorrect\":false}]",
