    "type": "technical",
    "questionType": "mcq",
    "prompt": "What is Kubernetes Role-Based Access Control (RBAC)?",
    "optionsJson": "[{\"id\":\"opt-c2-14-1\",\"text\":\"Regulates access to Kubernetes API resources based on the roles assigned to users and ServiceAccounts\",\"isCorrect\":true},{\"id\":\"opt-c2-14-2\",\"text\":\"Restricts physical access to data center server rooms\",\"isCorrect\":false},{\"id\":\"opt-c2-14-3\",\"text\":\"Controls CPU core allocation for Docker containers\",\"isCorrect\":false},{\"id\":\"opt-c2-14-4\",\"text\":\"Limits network bandwidth between cloud regions\",\"isCorrect\":false}]",
