    "skillId": "skill-k8s",
    "type": "technical",
    "questionType": "mcq",
    "prompt": "What is a Kubernetes NetworkPolicy?",
    "optionsJson": "[{\"id\":\"opt-c2-15-1\",\"text\":\"Specifies packet filtering rules to control ingress and egress traffic flow at the IP and port level between pods\",\"isCorrect\":true},{\"id\":\"opt-c2-15-2\",\"text\":\"Sets pricing plans for cloud bandwidth\",\"isCorrect\":false},{\"id\":\"opt-c2-15-3\",\"text\":\"Controls DNS domain registration for cluster services\",\"isCorrect\":false},{\"id\":\"opt-c2-15-4\",\"text\":\"Manages Wi-Fi connections in office buildings\",\"isCorrect\":false}]",
