    "prompt": "What is the role of Kube-Proxy on worker nodes?",
    "optionsJson": "[{\"id\":\"opt-c2-19-1\",\"text\":\"Maintains network rules on nodes to allow network communication to Pods from inside or outside the cluster via IPVS/iptables\",\"isCorrect\":true},{\"id\":\"opt-c2-19-2\",\"text\":\"Caches Docker image layers locally\",\"isCorrect\":false},{\"id\":\"opt-c2-19-3\",\"text\":\"Scans container logs for security threats\",\"isCorrect\":false},{\"id\":\"opt-c2-19-4\",\"text\":\"Issues OAuth tokens for web users\",\"isCorrect\":false}]",
