    "optionsJson": "[{\"id\":\"opt-u1-17-1\",\"text\":\"Users have a propensity to best remember the first (primacy) and last (recency) items in a series or navigation list\",\"isCorrect\":true},{\"id\":\"opt-u1-17-2\",\"text\":\"Users always click on the middle item in a list\",\"isCorrect\":false},{\"id\":\"opt-u1-17-3\",\"text\":\"Users read items from right to left on tablet screens\",\"isCorrect\":false},{\"id\":\"opt-u1-17-4\",\"text\":\"Items in alphabetical order are clicked 50% more often\",\"isCorrect\":false}]",
