    "prompt": "What is the difference between User Need and Feature Request in product discovery?",
    "optionsJson": "[{\"id\":\"opt-u1-18-1\",\"text\":\"A feature request is a proposed solution (e.g. \\\"Add an export to CSV button\\\"); a user need is the underlying problem (e.g. \\\"Share weekly sales figures with stakeholders\\\")\",\"isCorrect\":true},{\"id\":\"opt-u1-18-2\",\"text\":\"Feature requests are always implemented immediately; user needs are ignored\",\"isCorrect\":false},{\"id\":\"opt-u1-18-3\",\"text\":\"Feature requests come only from developers; user needs from CEOs\",\"isCorrect\":false},{\"id\":\"opt-u1-18-4\",\"text\":\"There is no difference between them\",\"isCorrect\":false}]",
