    "skillId": "skill-problem-solving",
    "type": "aptitude",
    "questionType": "mcq",
    "prompt": "If the price of sugar increases by 25%, by what percentage must a household reduce its consumption so that the total expenditure remains unchanged?",
    "optionsJson": "[{\"id\":\"opt-q1-01-1\",\"text\":\"20%\",\"isCorrect\":true},{\"id\":\"opt-q1-01-2\",\"text\":\"25%\",\"isCorrect\":false},{\"id\":\"opt-q1-01-3\",\"text\":\"15%\",\"isCorrect\":false},{\"id\":\"opt-q1-01-4\",\"text\":\"16.67%\",\"isCorrect\":false}]",
