    "practiceSetId": "set-quant-1",
    "domain": "Quantitative Aptitude",
    "skillId": "skill-problem-solving",
    "type": "aptitude",
    "questionType": "mcq",
    "prompt": "The average age of a class of 30 students is 15 years. If the teacher age is included, the average age increases by 1 year. What is the teacher age?",
    "optionsJson": "[{\"id\":\"opt-q1-05-1\",\"text\":\"46 years\",\"isCorrect\":true},{\"id\":\"opt-q1-05-2\",\"text\":\"45 years\",\"isCorrect\":false},{\"id\":\"opt-q1-05-3\",\"text\":\"40 years\",\"isCorrect\":false},{\"id\":\"opt-q1-05-4\",\"text\":\"50 years\",\"isCorrect\":false}]",
    "weight": 1,
