    "type": "aptitude",
    "questionType": "mcq",
    "prompt": "In an examination, 35% of students failed in Mathematics and 25% in English. If 10% failed in both subjects, what percentage of students passed in both subjects?",
    "optionsJson": "[{\"id\":\"opt-q1-17-1\",\"text\":\"50%\",\"isCorrect\":true},{\"id\":\"opt-q1-17-2\",\"text\":\"60%\",\"isCorrect\":false},{\"id\":\"opt-q1-17-3\",\"text\":\"45%\",\"isCorrect\":false},{\"id\":\"opt-q1-17-4\",\"text\":\"55%\",\"isCorrect\":false}]",
